export class IndividualWarmaneAutoImporter<SpecType extends Spec> extends Importer {
	private readonly simUI: IndividualSimUI<SpecType>;
	private serverSelect: HTMLSelectElement | null = null;
	private nameInput: HTMLInputElement | null = null;
	private profileLink: HTMLAnchorElement | null = null;
	private talentsLink: HTMLAnchorElement | null = null;
	private profileInput: HTMLTextAreaElement | null = null;
	private talentsInput: HTMLTextAreaElement | null = null;

	constructor(parent: HTMLElement, simUI: IndividualSimUI<SpecType>) {
		super(parent, simUI, 'Warmane Character Import', false);
		this.simUI = simUI;

		const servers = ['Onyxia', 'Icecrown', 'Lordaeron', 'Blackrock']; 

		this.descriptionElem.innerHTML = `
			<p>Import gear, gems, enchants, talents, glyphs, race, and professions directly from Warmane.</p>
			<ol>
				<li>Select your <b>Realm</b> and enter your <b>Character Name</b>.</li>
				<li>Click the <b>Profile</b> link. Right-click the page, click <b>View Page Source (Ctrl+U)</b>, copy all text (Ctrl+A, Ctrl+C), and paste it in the first box.</li>
				<li>Click the <b>Talents</b> link. Do the same thing, and paste the source code in the second box.</li>
			</ol>
		`;

		this.body.innerHTML = `
			<div class="import-description">${this.descriptionElem.innerHTML}</div>
			<div class="row mb-3">
				<div class="col-md-4">
					<label class="form-label">Realm</label>
					<select class="form-select warmane-server-select">
						${servers.map(s => `<option value="${s}">${s}</option>`).join('')}
					</select>
				</div>
				<div class="col-md-8">
					<label class="form-label">Character Name</label>
					<input type="text" class="form-control warmane-name-input" placeholder="Roguealah">
				</div>
			</div>
			
			<hr>

			<div class="row mb-3">
				<div class="col-md-3 d-flex align-items-center">
					<a href="#" target="_blank" class="btn btn-outline-primary warmane-profile-link disabled w-100">
						<i class="fas fa-external-link-alt"></i> Profile
					</a>
				</div>
				<div class="col-md-9">
					<textarea class="form-control warmane-profile-input" rows="2" placeholder="Paste Profile HTML Source here..."></textarea>
				</div>
			</div>

			<div class="row mb-3">
				<div class="col-md-3 d-flex align-items-center">
					<a href="#" target="_blank" class="btn btn-outline-success warmane-talents-link disabled w-100">
						<i class="fas fa-external-link-alt"></i> Talents
					</a>
				</div>
				<div class="col-md-9">
					<textarea class="form-control warmane-talents-input" rows="2" placeholder="Paste Talents HTML Source here..."></textarea>
				</div>
			</div>
		`;

		this.serverSelect = this.body.querySelector('.warmane-server-select');
		this.nameInput = this.body.querySelector('.warmane-name-input');
		this.profileLink = this.body.querySelector('.warmane-profile-link');
		this.talentsLink = this.body.querySelector('.warmane-talents-link');
		this.profileInput = this.body.querySelector('.warmane-profile-input');
		this.talentsInput = this.body.querySelector('.warmane-talents-input');

		// Dynamically update the links when the user types their name/server
		const updateLinks = () => {
			const charName = this.nameInput?.value.trim();
			const realm = this.serverSelect?.value;
			if (charName && realm) {
				if (this.profileLink) {
					this.profileLink.href = `https://armory.warmane.com/character/${charName}/${realm}/profile`;
					this.profileLink.classList.remove('disabled', 'btn-outline-primary');
					this.profileLink.classList.add('btn-primary');
				}
				if (this.talentsLink) {
					this.talentsLink.href = `https://armory.warmane.com/character/${charName}/${realm}/talents`;
					this.talentsLink.classList.remove('disabled', 'btn-outline-success');
					this.talentsLink.classList.add('btn-success');
				}
			} else {
				if (this.profileLink) {
					this.profileLink.removeAttribute('href');
					this.profileLink.classList.add('disabled', 'btn-outline-primary');
					this.profileLink.classList.remove('btn-primary');
				}
				if (this.talentsLink) {
					this.talentsLink.removeAttribute('href');
					this.talentsLink.classList.add('disabled', 'btn-outline-success');
					this.talentsLink.classList.remove('btn-success');
				}
			}
		};

		this.nameInput?.addEventListener('input', updateLinks);
		this.serverSelect?.addEventListener('change', updateLinks);
	}

	async onImport() {
		const profileHtml = this.profileInput?.value.trim();
		const talentsHtml = this.talentsInput?.value.trim();

		if (!profileHtml || profileHtml.length < 100) {
			alert("Please paste the valid HTML source code from your Warmane Profile page into the first box.");
			return;
		}

		this.importButton.disabled = true;
		this.importButton.innerText = 'Parsing...';

		try {
			// Parse the gear, race, and professions from the pasted Profile HTML
			const { equipmentSpec, parsedRace, parsedProfessions } = this.parseWarmaneProfileHtml(profileHtml);
			
			// Parse the talents and glyphs from the pasted Talents HTML (if provided)
			let talentsStr = '';
			let glyphs: Glyphs | null = null;
			
			if (talentsHtml && talentsHtml.length > 100) {
				const parsed = this.parseWarmaneTalentsHtml(talentsHtml);
				talentsStr = parsed.talentsStr;
				glyphs = parsed.glyphs;
			}

			const charClass = this.simUI.player.getClass();
			const finalRace = parsedRace ? parsedRace : this.simUI.player.getRace();

			await this.finishIndividualImport(this.simUI, charClass, finalRace, equipmentSpec, talentsStr, glyphs, parsedProfessions);
			
			// Clear the boxes after successful import
			if (this.profileInput) this.profileInput.value = '';
			if (this.talentsInput) this.talentsInput.value = '';

		} catch (e: any) {
			alert(`Import error: ${e.message}\n\nMake sure you copied the "Page Source" (HTML code) and not just the text on the screen.`);
		} finally {
			this.importButton.disabled = false;
			this.importButton.innerHTML = '<i class="fa fa-download"></i> Import';
		}
	}

	private parseWarmaneProfileHtml(html: string): { equipmentSpec: EquipmentSpec, parsedRace: Race | null, parsedProfessions: Profession[] } {
		const parser = new DOMParser();
		const doc = parser.parseFromString(html, 'text/html');

		let parsedRace: Race | null = null;
		const levelRaceClassText = doc.querySelector('.level-race-class')?.textContent?.trim() || '';
		
		const possibleRaces = ['Blood Elf', 'Draenei', 'Dwarf', 'Gnome', 'Human', 'Night Elf', 'Orc', 'Tauren', 'Troll', 'Undead'];
		for (const pr of possibleRaces) {
			if (levelRaceClassText.includes(pr)) {
				parsedRace = nameToRace(pr.replace(/\s+/g, ''));
				break;
			}
		}

		const parsedProfessions: Profession[] = [];
		const profStubs = Array.from(doc.querySelectorAll('.profskills .stub'));

		for (const stub of profStubs) {
			const textDiv = stub.querySelector('.text');
			if (!textDiv) continue;

			const textClone = textDiv.cloneNode(true) as HTMLElement;
			const span = textClone.querySelector('.value');
			if (span) span.remove();

			const profNameRaw = textClone.textContent?.trim() || '';

			const valSpan = textDiv.querySelector('.value');
			const valText = valSpan?.textContent?.trim() || '';
			const match = valText.match(/(\d+)\s*\//);
			const level = match ? parseInt(match[1], 10) : 0;

			if (level >= 350) {
				const profEnum = nameToProfession(profNameRaw);
				if (profEnum !== Profession.ProfessionUnknown) {
					parsedProfessions.push(profEnum);
				}
			}
		}

		const finalProfessions = parsedProfessions.slice(0, 2);

		const equipmentSpec = EquipmentSpec.create();
		const itemsBySlot: (ItemSpec | null)[] = new Array(19).fill(null);

		const itemNodes = Array.from(doc.querySelectorAll('a[rel^="item="]'));
		if (itemNodes.length === 0) {
			throw new Error("No gear found. Make sure you copied the HTML from the Profile page.");
		}

		itemNodes.forEach(node => {
			const rel = node.getAttribute('rel') || '';
			const itemSpec = ItemSpec.create();

			const itemMatch = rel.match(/item=(\d+)/);
			if (itemMatch) itemSpec.id = parseInt(itemMatch[1], 10);

			const enchMatch = rel.match(/ench=(\d+)/);
			if (enchMatch) itemSpec.enchant = parseInt(enchMatch[1], 10);

			const gemsMatch = rel.match(/gems=([\d:]+)/);
			if (gemsMatch) {
				itemSpec.gems = gemsMatch[1]
					.split(':')
					.map(id => parseInt(id, 10))
					.filter(id => id > 0)
					.map(gemEnchantId => WARMANE_GEM_MAP[gemEnchantId as keyof typeof WARMANE_GEM_MAP] || 0); 
			}

			if (itemSpec.id) {
				const itemSlotDiv = node.closest('.item-slot');
				const parentColumn = itemSlotDiv?.parentElement;
				let detectedSlot: ItemSlot | null = null;

				if (itemSlotDiv && parentColumn) {
					const slotIndex = Array.from(parentColumn.children).indexOf(itemSlotDiv);

					if (parentColumn.classList.contains('item-left')) {
						const leftSlots = [ItemSlot.ItemSlotHead, ItemSlot.ItemSlotNeck, ItemSlot.ItemSlotShoulder, ItemSlot.ItemSlotBack, ItemSlot.ItemSlotChest, null, null, ItemSlot.ItemSlotWrist];
						detectedSlot = leftSlots[slotIndex];
					} else if (parentColumn.classList.contains('item-right')) {
						const rightSlots = [ItemSlot.ItemSlotHands, ItemSlot.ItemSlotWaist, ItemSlot.ItemSlotLegs, ItemSlot.ItemSlotFeet, ItemSlot.ItemSlotFinger1, ItemSlot.ItemSlotFinger2, ItemSlot.ItemSlotTrinket1, ItemSlot.ItemSlotTrinket2];
						detectedSlot = rightSlots[slotIndex];
					} else if (parentColumn.classList.contains('item-bottom')) {
						const bottomSlots = [ItemSlot.ItemSlotMainHand, ItemSlot.ItemSlotOffHand, ItemSlot.ItemSlotRanged];
						detectedSlot = bottomSlots[slotIndex];
					}
				}

				if (detectedSlot !== null) {
					itemsBySlot[detectedSlot] = itemSpec;
				}
			}
		});

		equipmentSpec.items = itemsBySlot.map(item => item || ItemSpec.create());
		
		return { equipmentSpec, parsedRace, parsedProfessions: finalProfessions };
	}

	private parseWarmaneTalentsHtml(html: string): { talentsStr: string, glyphs: Glyphs | null } {
		const parser = new DOMParser();
		const doc = parser.parseFromString(html, 'text/html');
		
		let talentsStr = '';
		let glyphs: Glyphs | null = null;

		const activeSpecTd = doc.querySelector('td.selected[data-spec]');
		if (!activeSpecTd) return { talentsStr, glyphs };
		
		const activeSpecId = activeSpecTd.getAttribute('data-spec');

		const activeTalentContainer = doc.querySelector(`#spec-${activeSpecId}`);
		if (activeTalentContainer) {
			const trees = Array.from(activeTalentContainer.querySelectorAll('.talent-frame'));
			
			talentsStr = trees.map(tree => {
				const points = Array.from(tree.querySelectorAll('.talent-points'))
					.map(pt => pt.textContent?.trim().charAt(0) || '0');
				
				let treeStr = points.join('');
				while (treeStr.endsWith('0')) {
					treeStr = treeStr.slice(0, -1);
				}
				return treeStr;
			}).join('-');
		}

		const activeGlyphsContainer = doc.querySelector(`div[data-glyphs="${activeSpecId}"]`);
		if (activeGlyphsContainer) {
			const getSpellId = (node: Element) => {
				const match = (node as HTMLAnchorElement).href.match(/spell=(\d+)/);
				return match ? parseInt(match[1], 10) : 0;
			};

			const majorNodes = Array.from(activeGlyphsContainer.querySelectorAll('.glyph.major a'));
			const minorNodes = Array.from(activeGlyphsContainer.querySelectorAll('.glyph.minor a'));

			const majorIds = majorNodes.map(getSpellId);
			const minorIds = minorNodes.map(getSpellId);

			glyphs = Glyphs.create({
				major1: majorIds[0] ? this.simUI.sim.db.glyphSpellToItemId(majorIds[0]) : 0,
				major2: majorIds[1] ? this.simUI.sim.db.glyphSpellToItemId(majorIds[1]) : 0,
				major3: majorIds[2] ? this.simUI.sim.db.glyphSpellToItemId(majorIds[2]) : 0,
				minor1: minorIds[0] ? this.simUI.sim.db.glyphSpellToItemId(minorIds[0]) : 0,
				minor2: minorIds[1] ? this.simUI.sim.db.glyphSpellToItemId(minorIds[1]) : 0,
				minor3: minorIds[2] ? this.simUI.sim.db.glyphSpellToItemId(minorIds[2]) : 0,
			});
		}

		return { talentsStr, glyphs };
	}
}

const throwCataError = () => {
	throw new Error(`WowSims does not support the Cata Pre-patch.
Please use: https://wowsims.github.io/cata/ instead`);
};

function glyphNameToID(glyphName: string, glyphsConfig: Record<number, GlyphConfig>): number {
	if (!glyphName) {
		return 0;
	}

	for (const glyphIDStr in glyphsConfig) {
		if (glyphsConfig[glyphIDStr].name == glyphName) {
			return parseInt(glyphIDStr);
		}
	}
	throw new Error(`Unknown glyph name '${glyphName}'`);
}

function glyphToID(glyph: string | JsonObject, db: Database, glyphsConfig: Record<number, GlyphConfig>): number {
	if (typeof glyph === 'string') {
		// Legacy version: AddOn exports Glyphs by name (string) only. Names must be in English.
		return glyphNameToID(glyph, glyphsConfig);
	}
	// New version exports glyph information in a table that includes the name and the glyph spell ID.
	return db.glyphSpellToItemId(glyph['spellID'] as number);
}
